72	/**
73	 * Permission value type - simple or pattern-based
74	 * Pattern-based permissions use glob patterns as keys (e.g., "*.ts": "allow")
75	 */
76	export type OpenCodePermissionValue =
77	  | 'ask'
78	  | 'allow'
79	  | 'deny'
80	  | Record<string, 'ask' | 'allow' | 'deny'>;
81	
82	/**
83	 * Permission configuration for specific tools
84	 *
85	 * Supports both simple values ('ask', 'allow', 'deny') and pattern-based
86	 * configuration using glob patterns for granular control.
87	 *
88	 * @example
89	 * ```yaml
90	 * permission:
91	 *   bash: allow  # Simple: allow all bash commands
92	 *   edit:
93	 *     "*.md": allow      # Pattern: allow editing markdown files
94	 *     "src/**": ask      # Pattern: ask for src directory
95	 *   external_directory: deny  # Deny access outside working dir
96	 * ```
97	 */
98	export interface OpenCodePermissionConfig {
99	  /** Shell command execution permission */
100	  bash?: OpenCodePermissionValue;
101	  /** File editing permission */
102	  edit?: OpenCodePermissionValue;
103	  /** Web fetching permission */
104	  webfetch?: OpenCodePermissionValue;
105	  /** Prevents infinite agent loops (added in v1.1.1) */
106	  doom_loop?: OpenCodePermissionValue;
107	  /** Access to directories outside the working directory (added in v1.1.1) */
108	  external_directory?: OpenCodePermissionValue;
109	}
110	
111	/**
112	 * Custom agent configuration
