12	/**
13	 * Supported wrapper script types for language-specific providers.
14	 */
15	export type WrapperType = 'python' | 'ruby' | 'golang';
16	
17	/**
18	 * Mapping of wrapper types to their subdirectory names.
19	 * These correspond to the directory structure under src/ and dist/src/.
20	 */
21	const WRAPPER_SUBDIRS: Record<WrapperType, string> = {
22	  python: 'python',
23	  ruby: 'ruby',
24	  golang: 'golang',
25	};
26	
27	/**
28	 * Cache for wrapper directory paths to avoid repeated path construction.
29	 */
30	const wrapperDirCache: Partial<Record<WrapperType, string>> = {};
31	
32	/**
33	 * Returns the directory containing wrapper scripts for the specified language.
34	 *
35	 * This function provides a consistent way to locate wrapper scripts (wrapper.py,
36	 * wrapper.rb, wrapper.go, etc.) that works correctly in both development and
37	 * production (bundled) environments.
38	 *
39	 * Directory resolution:
40	 * - Development (tsx): src/{python|ruby|golang}/
41	 * - Production (bundled): dist/src/{python|ruby|golang}/
42	 *
43	 * Results are cached for performance.
44	 *
45	 * @param type - The wrapper type ('python', 'ruby', or 'golang')
46	 * @returns The absolute path to the wrapper directory
47	 *
48	 * @example
49	 * ```typescript
50	 * // Get Python wrapper path
51	 * const pythonDir = getWrapperDir('python');
52	 * const wrapperPath = path.join(pythonDir, 'wrapper.py');
53	 *
54	 * // Get Ruby wrapper path
55	 * const rubyDir = getWrapperDir('ruby');
56	 * const wrapperPath = path.join(rubyDir, 'wrapper.rb');
57	 * ```
58	 */
59	export function getWrapperDir(type: WrapperType): string {
60	  if (wrapperDirCache[type]) {
61	    return wrapperDirCache[type]!;
62	  }
63	
64	  const baseDir = getDirectory();
65	  const result = path.join(baseDir, WRAPPER_SUBDIRS[type]);
66	  wrapperDirCache[type] = result;
67	
68	  logger.debug(`Resolved ${type} wrapper directory: ${result}`);
69	  return result;
70	}
71	
72	/**
73	 * Clears the wrapper directory cache.
74	 * Primarily useful for testing to ensure fresh path resolution.
75	 */
76	export function clearWrapperDirCache(): void {
77	  for (const key of Object.keys(wrapperDirCache) as WrapperType[]) {
78	    delete wrapperDirCache[key];
79	  }
80	}
