82	/**
83	 * Resolves the entry point path for an npm package, handling ESM-only packages
84	 * with restrictive `exports` fields.
85	 *
86	 * ## Why this function exists
87	 *
88	 * Some ESM-only packages (like `@openai/codex-sdk`) have restrictive `exports` fields:
89	 *
90	 * ```json
91	 * {
92	 *   "type": "module",
93	 *   "exports": {
94	 *     ".": { "import": "./dist/index.js" }
95	 *   }
96	 * }
97	 * ```
98	 *
99	 * This causes problems with Node.js's `require.resolve()`:
100	 * - `require.resolve('@openai/codex-sdk')` fails with "No exports main defined"
101	 *   because there's no `"require"` or `"default"` condition.
102	 *
103	 * ## Solution
104	 *
105	 * This function uses `exsolve` which implements Node's ESM resolution algorithm,
106	 * correctly handling all `exports` field variations:
107	 * - Direct string exports: `"exports": "./index.js"`
108	 * - Shorthand object: `"exports": { ".": "./index.js" }`
109	 * - Conditional exports: `"exports": { ".": { "import": "./index.js" } }`
110	 * - Nested conditionals, array fallbacks, pattern exports, etc.
111	 *
112	 * @param packageName - The npm package name (e.g., '@openai/codex-sdk')
113	 * @param baseDir - The directory to resolve from (should contain node_modules)
114	 * @returns The absolute path to the package entry point, or null if not found
115	 *
116	 * @example
117	 * ```typescript
118	 * // Resolve from current directory
119	 * const codexPath = resolvePackageEntryPoint('@openai/codex-sdk', process.cwd());
120	 * if (codexPath) {
121	 *   const module = await importModule(codexPath);
122	 * }
123	 * ```
124	 */
125	export function resolvePackageEntryPoint(packageName: string, baseDir: string): string | null {
126	  // Use exsolve which implements Node's ESM resolution algorithm
127	  // The `from` URL tells exsolve where to start looking for node_modules
128	  const from = pathToFileURL(path.join(baseDir, 'package.json')).href;
129	
130	  const resolved = resolveModulePath(packageName, {
131	    from,
132	    // Conditions in priority order: Node.js-specific, ESM, CommonJS, default fallback
133	    conditions: ['node', 'import', 'require', 'default'],
134	    // Return undefined instead of throwing when package not found
135	    try: true,
136	  });
137	
138	  // Normalize the path to use platform-specific separators (forward slashes on Unix, backslashes on Windows)
139	  return resolved ? path.normalize(resolved) : null;
140	}
