142	// Global variable defined by tsup at build time
143	// undefined in development (tsx) and Jest tests
144	declare const BUILD_FORMAT: 'esm' | 'cjs' | undefined;
145	
146	/**
147	 * ESM replacement for __dirname - guarded for dual CJS/ESM builds.
148	 *
149	 * This is the canonical way to get the current directory in dual ESM/CJS code.
150	 * Use this instead of implementing the try-catch pattern in each file.
151	 *
152	 * Build contexts:
153	 * - ESM (production/bundled): BUILD_FORMAT='esm', import.meta.url is valid
154	 * - CJS (library build): BUILD_FORMAT='cjs', import.meta.url may be empty, __dirname available
155	 * - Development (tsx): BUILD_FORMAT=undefined, import.meta.url is valid
156	 * - Vitest tests: BUILD_FORMAT=undefined, import.meta is valid in ESM mode
157	 *
158	 * The try-catch is necessary because `import.meta` syntax itself causes a SyntaxError
159	 * in CJS environments (Node require), not just an undefined value.
160	 */
161	export function getDirectory(): string {
162	  // In bundled CJS builds, skip the ESM path entirely - import.meta.url will be empty
163	  if (typeof BUILD_FORMAT !== 'undefined' && BUILD_FORMAT === 'cjs') {
164	    // @ts-ignore - __dirname exists in CJS builds
165	    return __dirname;
166	  }
167	
168	  try {
169	    // Try ESM approach - import.meta.url is available in ESM and tsx
170	    // This will throw SyntaxError in CJS environments where import.meta is invalid syntax
171	    const url = import.meta.url;
172	    if (url && url !== '') {
173	      return path.dirname(fileURLToPath(url));
174	    }
175	  } catch {
176	    // Expected in CJS environments where import.meta syntax is invalid
177	    // Fall through to __dirname fallback
178	  }
179	
180	  // Fall back to CJS __dirname (available in CJS builds)
181	  // @ts-ignore - __dirname exists in CJS but not in ESM types
182	  if (typeof __dirname !== 'undefined') {
183	    // @ts-ignore
184	    return __dirname;
185	  }
186	
187	  // This should never happen in normal operation
188	  throw new Error(
